// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":311,"question":"فضيلة الشيخ، إنني ولله الحمد من النِّساء اللاتي تفضّل الله عليهنَّ بالهداية إلى طريقه المُستقيم، وكذلك أنعم عليَّ بالزواج من شابٍّ كذلك من المُهتدين ولله الحمد، ومشكلتي التي أريد عرضها عليكم يا سماحة الشيخ هي أن زوجي كثيرًا ما يغضب عليَّ لأسبابٍ تافهةٍ أحيانًا، وأحيانًا تستحق الغضب، ونتيجة لكثرة هذا الغضب منه لم أتحمل البقاء معه، وخرجتُ من بيتي، ولم أعد إليه إلى الآن، ولكني بعد خروجي من بيت زوجي أنَّبَنِي الكثير من الصَّديقات، ونصحنني بالعودة بقولهنَّ: إنَّكِ آثمةٌ، وأن الملائكة تلعنُكِ إلى أن تُرضي زوجك، وأنا الآن في حيرةٍ من أمري: هل أتنازل وأذهب إلى بيتي وأتحمّل كل المآسي أم أبقى في بيت أهلي وأنتظر ورقةَ طلاقي؟","title":"ما النصيحة فيما يقع بين الزوجين من خلاف؟","answer":"الجواب: الذي أنصحك به العودة ما دام الله قد هداه إلى الإسلام، وهو طيب، وأنت كذلك طيبة، فاحمدي الله على ذلك، وكل إنسانٍ عنده تقصير، وعنده غلط، وعنده غضب، ما في الدنيا زوجٌ سالمٌ ما يغضب أبدًا ولا يحصل منه شيءٌ، كلٌّ فيه نقصٌ: كل بني آدم خطَّاء.\nفالواجب عليك أن ترجعي إلى بيته، وأن تُعامليه بالتي هي أحسن، وأن تكوني طيبة الأخلاق متحمّلةً لهذا الأمر، وأن تحرصي على الكلام الطيب الذي يُزيل عنه الغضب، يُخفف عنه الغضب، احرصي على الكلام الطيب، واللين في الكلام، والتماس أسباب رضاه، والحرص على ذلك، وأبشري بالخير والعاقبة الحميدة: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nهذه نصيحتي لك: العودة والحرص على بذل الأسباب التي تُرضيه عنك وتجعله دائمًا على حالٍ حسنةٍ، وعلى بِشْرٍ، وعلى كلامٍ طيبٍ، ومتى فعلت ما تستطيعين من الخير والتَّحمل والأسلوب الحسن والكلمات الطيبة ضدّ كلامه الشديد؛ فإنَّ العاقبة تكون لك إن شاء الله، وهو يهديه الله.","link":"https://binbaz.org.sa/fatwas/4314/ما-النصيحة-فيما-يقع-بين-الزوجين-من-خلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0361.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":1547,"question":"{التي} في سورة المجادلة هل تعني أنه خلاف عادي بين الزوج والزوجة أو خلاف طلاق؟","title":"معنى الجدال الذي جاء في سورة المجادلة","answer":"الجواب:\nتجادل في زوجها أنه فعل وأنه فعل، ثم جرى ما جرى من الظهار، المقصود أن الزوج يكون عنده حلم وصبر وتَحَمُّل، ولو مع المجادلة، لا يعجل في الظهار، ولا يعجل في الطلاق، يكون عنده حلم وصبر، فلا يُحَرِّم ولا يُطَلِّقْ، يكون عنده تَحَمُّل ولا يضرب.","link":"https://binbaz.org.sa/fatwas/21648/معنى-الجدال-الذي-جاء-في-سورة-المجادلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فائدة اجتماعية من سورة المجادلة.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":1862,"question":"إذا كان لا يُصلِّي ودعاها هل يجوز لها أن ترفض؟","title":"حكم هجر المرأة فراش زوجها الذي لا يصلي","answer":"الجواب:\nإذا كان ما يُصلي فالنكاح باطل، ما تحلُّ له.\nس: طيب، وإذا كان لا يُصلي مع الجماعة وأرادت اجتنابَ فراشه تأديبًا له؟\nج: تسمع وتُطيع وتنصحه، أما إذا كان يترك الصلاة فتركها كفر.","link":"https://binbaz.org.sa/fatwas/21971/حكم-هجر-المراة-فراش-زوجها-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رجل لا يصلي ودعا زوجته للفراش فهل لها أن تمتنع.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":2006,"question":"في العصر الحاضر هناك من يفسر (وَأْد البنات) بتصعيب الزواج ومنع البنات من الزواج، يقول: أن هذا وَأْد معنوي؟","title":"حكم وصف منع زواج البنات بالوَأْد المعنوي","answer":"الجواب:\nلا ما هو بِوَأْد، لكن يجب على الأولياء أن يساعدوا في تزويج مولياتهم، وإلا ما يسمى \"وَأْد\"، لكن منعهن من حاجتهن من أسباب كثرة الفواحش، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22122/حكم-وصف-منع-زواج-البنات-بالواد-المعنوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تصعيب الزواج يعد من وأد البنات.mp3","categories":["مسائل متفرقة في النكاح","المشكلات الزوجية"]},{"id":3075,"question":"مَنْ قال إن الإتيان مِن الدُّبُر كُفْر عملي، هل هذا صحيح؟","title":"حكم إتيان المرأة مِنْ الدُّبُر","answer":"الجواب: هذا ما يجب، معصية من المعاصي.\nالسؤال: لكنه ليس كفرًا عمليًّا؟\nالشيخ: كُفْر أصغر.","link":"https://binbaz.org.sa/fatwas/23235/حكم-اتيان-المراة-من-الدبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إتيان المرأة من الدبر.mp3","categories":["مسائل متفرقة في النكاح","المشكلات الزوجية"]},{"id":6773,"question":"لي زوجة قائم عليها بكسوتها، وأكلها، وشربها، ومسكنها، ولكن تطلب مني فلم أستطع، ويحصل بيني، وبينها مشاكل يوميًا، وإنني كرهت دخول المنزل بسببها، فطلبت مني الطلاق، وهي حامل في الشهر التاسع، وأنا مستحمل ذلك، وعملت معها المستحيل لأرضيها، ولكنها ترفض، أفيدوني جزاكم الله خيرًا؟","title":"كيفية التصرف مع الزوجة المكثرة من الطلبات","answer":"الجواب: العاقل كريم الأخلاق، يعينه الله على إرضاء زوجته بالكلام الطيب، والألفاظ المعسولة الحسنة، والسيرة الحميدة، والعشرة الطيبة، وتهدأ بعد ذلك، المرأة ضعيفة، متى رأت من زوجها اللطف، والإحسان، والعشرة الطيبة، ولين الكلام، والوعد الحسن؛ طابت أخلاقها، واستقامت أمورها، لكن مع العنف، والشدة، والتكبر، وعدم المبالاة بكلامها هذا يزيد الطين بلة، ويسبب طول المشاكل، واستمرار المشاكل. فينبغي للرجل أن يكون عنده دين، وعنده عطف، وعنده لطف، وعنده رفق، وأسلوب حسن، أبشري، إن شاء الله إذا تيسر، أمهليني، إن شاء الله أبشري بالخير، يا بنت فلان، يا أم فلان، أبشري بالخير، كلام طيب، لسان حسن، ولو كذب، ما يضر، لا بأس أن يحدثها وهو يكذب، حتى يفتح الله عليه .. تقول أم كلثوم بنت عقبة -رضي الله عنها-: سمعت النبي ﷺ يرخص في ثلاث، ما سمعته يرخص في شيء من الكذب إلا في ثلاث: ثم ذكر من الثلاث: حديث الرجل امرأته، والمرأة زوجها الأولى في الحرب، والثانية في الإصلاح بين الناس، والثالثة في حديث الرجل امرأته، والمرأة زوجها، فلا بأس أن يحدثها فيكذب، وأن تحدثه فتكذب، إذا كان فيما يتعلق بهما، وخاصتهما، وما يرضي أحدهما عن الآخر، فيقول: سوف أفعل، سوف أشتري لك كذا، وسوف أفعل كذا، وسوف كذا، وسوف نشتري فلة، ونشتري الفلة المناسبة كذا، يعني يعدها، أوعادًا حسنة، ولو في نيته أنه ما يفي بها؛ لأنه عاجز عنها، لكن من باب تطييب الخواطر، ومن باب الإحسان، ومن باب اللطف، ومن باب تلبية الرغبات، ولو بالكلام الطيب؛ حتى يفتح الله -جل وعلا- عليه، والمؤمن .. الخلق حسن الخلق، طيب الكلام، وعدم العنف والشدة. السؤال: هل الأولى تركه؟ الجواب: إذا ما دعت إليه الحاجة لا بأس، الأمر جائز، وإذا ما دعت إليه الحاجة لا حاجة للكذب، لكن إذا دعت إليه الحاجة لا بأس.","link":"https://binbaz.org.sa/fatwas/2636/كيفية-التصرف-مع-الزوجة-المكثرة-من-الطلبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1132.mp3","categories":["الحقوق الزوجية","المشكلات الزوجية"]},{"id":7936,"question":"من المرسل أحمد عبد الله جاد من بورما، يقول: السلام عليكم ورحمة الله وبركاته، أرجو عرض هذا السؤال على فضيلة الشيخ عبد العزيز بن باز ، وإذاعة الرد مع جزيل الشكر، يقول: ابتليت بزوجة تكره المعاشرة الزوجية أي: الجنس، ولا تعرف حقوق الزوج وتنام في غرفة أخرى، ولا تعرف الزينة ونصحتها وأرشدتها ووجهتها، ولكن دون جدوى، فهل إذا تزوجت بأخرى وهجرتها أؤثم، علماً بأن لي منها أولاد وبنات على المدى الطويل ولا سبيل لإصلاحها أفيدوني جزاكم الله خير؟","title":"كيفية العمل مع المرأة التي لا تحسن معاشرة زوجها","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، والواجب عليها أن تحسن العشرة، وأن تمكنه من نفسها إذا أراد قضاء حاجته منها، وأن تخاطبه بالتي هي أحسن، وأن تنام معه في الفراش إذا طلب ذلك، هذا هو الواجب عليها؛ لأن الله يقول : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] لهن من المعاشرة الطيبة مثل الذي عليهن، الله أمر بالمعاشرة الطيبة فقال: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] فكما يجب على الزوج أن يعاشر بالمعروف فهي أيضاً عليها أن تعاشر بالمعروف، وللرجال على المرأة درجة، فعلم بذلك أن حق الرجل أكبر، وأن الواجب عليهما جميعاً التعاون على البر والتقوى والمعاشرة الطيبة بالكلام الطيب والفعل الطيب، عليها وعليه جميعاً، فإذا أصرت على أنها لا تمكنه من نفسها وعلى أنها تنفرد وحدها، وعلى أنها لا تعتني بنفسها من جهة الزينة والطيب، فهذا غلط منها وخطأ لا يجوز لها ذلك.\nولك -أيها السائل- أن تتزوج مطلقا، لك أن تتزوج بثانية وثالثة ورابعة لا حرج عليك، حتى ولو كانت من أحسن الناس طاعة وامتثالاً، لك أن تتزوج، لكن بهذه المثابة من باب أولى أن تتزوج؛ لأنها لم تقم بالواجب، ولم تمكنك مما يسبب عفتك وغض بصرك، فالمشروع لك في هذه الحال وأنت قادر أن تتزوج حتى تعف نفسك، وحتى تجد الراحة من هذا التعب، ولعلها بالزواج لعلها تنيب إلى رشدها، ولعلها ترجع عن غلطها هذا بسبب زواجك على غيرها، هذا هو الذي أرى في هذه المسألة، مع النصيحة لها والعناية بها وتوجيهها إلى الخير، وكذلك توصي أقاربها كأبيها وأخيها أو خالها أو عمها أن ينصحها وأن يوجهها إلى الخير، وكذلك أمها وجدتها وخالاتها يعني توصي من حولك من أقاربها بأن ينصحوها ويوجهوها إلى الخير؛ لأن هذا أمر يضرها ويضرك جميعا، ويضركما جميعاً، فإن استمعت واستقامت فالحمد لله، وإلا فأنت حر بحمد الله تستطيع أن تفارقها، تستطيع أن تتزوج ثانية وثالثة ورابعة، كل هذا بحمد الله لك ميسر إذا قدرت عليه، والله المستعان، ونسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/5457/كيفية-العمل-مع-المراة-التي-لا-تحسن-معاشرة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06606.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":7945,"question":"هذه الرسالة -يا سماحة الشيخ- وردتنا من مقدم الأسئلة المستمع (ع. س. م) من الرياض يقول فيها: السلام عليكم ورحمة الله وبركاته.. وبعد:رجل مريض بشلل نصفي وتأتي الصرعة مرة واحدة في كل شهر -ربنا يحفظنا ويحفظكم من هذا المرض- وله رغبة في معاشرة وجماع زوجته ولكن زوجته ترفض ذلك وتقول: إذا أنا أنجبت أولاد معك فإنني كالذي زنت، ما حكم الشريعة في تلك الزوجة وفقكم الله؟","title":"حكم رفض المرأة معاشرة زوجها المصاب بالصرع","answer":"الجواب: الواجب عليها أن تمكنه من نفسها؛ لأنها زوجته وعليها أن تمكنه من نفسها، فإذا كانت يعني قد كرهته من أجل الصرع فترفع أمرها إلى الحاكم ما دامت في عصمته وزوجته فله الحق أن يجامعها ويتصل بها وعليها الحق أن تمكنه من نفسها، أما إذا كانت لما أصابه الصرع كرهته وأحبت الفراق فهذا يرجع إلى المحكمة، لكن إذا كانت قد رضيت واستقرت معه والصرع معه فإنه يلزمها أن تمكنه من نفسها حتى يقضي وطره من ذلك، وإن كانت حرمت وقالت: عليها الحرام وهي زانية إذا مكنته من نفسها فعليها كفارة اليمين، إذا كانت حرمت أن تمكنه من نفسها فهذا في حكم اليمين وعليها كفارة اليمين: إطعام عشر مساكين إذا كانت حرمت ذلك، وأما إذا كانت لم تحرم فعليها أن تمكنه من نفسها ولا بأس عليها في ذلك ولا حرج؛ لأن الصرع يعرض ويزول، أما إذا كانت كرهته وتريد فراقه فهذا إلى المحكمة والمحكمة تنظر في ذلك.","link":"https://binbaz.org.sa/fatwas/5477/حكم-رفض-المراة-معاشرة-زوجها-المصاب-بالصرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06808.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8046,"question":"هذه رسالة وردتنا من المستمع يقول: من الجمهورية العراقية محافظة نينوى، الأخ خ م أ يقول: ما حكم من يقبل نهود زوجته أي: الثدي، ويقوم بعض رءوس الثدي أثناء بداية الزواج وكذا ... إلى آخره، هل في ذلك شيء أم لا؟","title":"حكم تقبيل ثدي الزوجة وعضه من باب المداعبة","answer":"الجواب: لا نعلم في هذا شيء، أقول: لا نعلم في تقبيل الثدي أو عضه ما فيه شيء، أو مصه مصاً هكذا من باب المداعبة، أما شرب اللبن والحليب الذي فيه تركه أوْلى، ترك شرب اللبن أوْلى نعم، وأما مجرد التقبيل أو مص النهد من دون شيء، أو عض اللعب وما فيه شيء يؤذي: ما نعلم فيه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/5845/حكم-تقبيل-ثدي-الزوجة-وعضه-من-باب-المداعبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08111.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8158,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8164,"question":"الرسالة التالية وصلت إلى البرنامج من العراق نينوى وباعثتها الأخت: حفصة يونس محمد ، أختنا تسأل مجموعة من الأسئلة، من بينها سؤال عن عمها الذي تزوج بامرأة جديدة فلم يهتم إلا بها وبأولادها وترك أولاد زوجته الأولى، الرأي لو تكرمتم سماحة الشيخ؟","title":"اهتمام الزوج بإحدى زوجتيه دون الأخرى","answer":"الجواب: الواجب نصيحته، الواجب نصيحته من إخوته ومن أصدقائه ينصحونه حتى يحسن في أم أولاده الأولى، وحتى يعرف لها حقها وفضلها، وأن لا ينساها ويعرض عنها ويبخسها حقها، فإن كان ولابد وليس له رغبة فيها فإنه يخيرها: إن شاءت صبرت على ما يسر الله منه وإن شاءت طلبت الطلاق، فإن طلبت الطلاق وجب عليه أن يطلق أو يعدل بينها وبين الجديدة، وليس له أن يحبسها ولا يعدل بل عليه أن يعدل بينهما أو يجيبها إلى طلب الطلاق فيطلق، وإذا طلقها أنفق عليها نفقة العدة طلقها طلقة واحدة السنة، أن يطلق واحدة فقط لا يطلق بالثلاث يطلق واحدة وينفق عليها نفقة العدة ويعرف لها فضلها، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237].\nفينبغي له أن لا ينسى حالها الأولى وأنها أم أولاده، فينبغي له أن يكرمها ويلاحظها ويطيب خاطرها بما تيسر له من المساعدة هكذا ينبغي للرجال الأخيار ذوي مكارم الأخلاق وذوي النفوس الرفيعة الطيبة، ولكن لا يلزمه أن يبقيها في حباله إذا شاء أن يطلق فله أن يطلق، وإن صبرت هي ولم تطلب الطلاق رجاء أن يعود إليها أو لأنها ليست في حاجة إلى الطلاق لأنها لا ترغب الزواج على غيره، فإذا صبرت فلا بأس، وهو ينبغي له أن يحسن إليها وأن يعرف لها حالها الأولى، وأن يجود عليها بما يسر الله له ولا ينساها، هذا هو المشروع له.\nوعلى أقاربه الطيبين أن ينصحوه حتى يعدل أو يطلق إذا طلبت الطلاق.\nنعم والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/5961/اهتمام-الزوج-باحدى-زوجتيه-دون-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10403.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8167,"question":"الرسالة التالية باعثها أخونا المهندس (س. ط) ويعمل في الكويت، يقول: خطبنا قبل سنة أنا وأخي بنات خالتنا، ولم يكن هناك أي شرط في عقد الزواج، وبعد كتب الكتاب يريد والدها أن نمتنع عن السكن مع أهلنا، مع العلم بأن عائلتنا صغيرة، ويريد كذلك أن نقطع المصروف عن أهلنا، وأن لا نكمل تعليم إخواننا، كما أنه يريد أن نمتنع عن زيارة أعمامنا وخالاتنا وأختنا وجميع الأقارب وأن لا يزورونا كذلك، ولقد أحضرناه للتفاهم بحضرة إمام المسجد إلا أنه تلفظ على والدتنا بكلام بذيء، وتطاول على الله عز وجل، ووسطنا له أكثر من شخص إلا أنه يصر على شروطه، ووالدي ووالدتنا يصران على تطليق البنات، ولا سيما الوالدة، هل نطيع والدتي ونطلق البنات أم ماذا، وما رأي الشرع في ذلك؟ أفيدونا أفادكم الله؟","title":"حكم طاعة الوالدين في طلاق الزوجة","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فالأولى تطليق البنات ومراعاة خاطر الوالدين، وهذه الشروط شروط قبيحة تفضي إلى قطيعة الرحم وتفضي إلى الشحناء بين الأقارب، وهذا كله ليس بطيب، وعمل أبي البنتين عمل رديء لا ينبغي، فإن وافق على نقل البنتين إلى بيوتكما عند أهلكما فالحمد لله وإلا فطلاقهما أولى، وإذا كانت البنتان ترغبان في النكاح ففي إمكانهما أن يرفعا الأمر إلى المحكمة حتى تحول المحكمة بين والديهما وبين رأيه القبيح، فهذا هو الذي نرى في هذا، المحكمة تنظر في الأمر، فإن لم تريا محاكمته فلا بأس، والتطليق أولى، ولعل الله أن يرزقكما خيراً من هاتين البنتين في الدين والدنيا، أما التسبب في قطيعة أرحامكم وعقوق والديكم فهذا شيء لا ينبغي ولا ينصح به من يخاف الله ويرجوه سبحانه وتعالى.\nوفق الله الجميع وهدى الجميع.","link":"https://binbaz.org.sa/fatwas/5962/حكم-طاعة-الوالدين-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10404.mp3","categories":["بر الوالدين","المشكلات الزوجية","الحقوق الزوجية"]},{"id":8922,"question":"الرسالة التالية وصلت إلى البرنامج من البحرين، باعثها أحد الإخوة من هناك يقول: أبو إبراهيم، أخونا له مجموعة من الأسئلة من بينها سؤال يقول: أرغب في الزواج من امرأة ثانية وأنا قادر على تكاليف الزواج وعلى الصرف على بيتين، وأجد في نفسي أنني أستطيع أن أعدل بين الزوجتين، لكني سمعت من بعض الإخوة أن زواج الثانية لابد له من شروط، كأن تكون الزوجة الأولى مريضة أو لا تنجب أو غير ذلك من الأسباب، فهل هذا صحيح أو أنه في الإمكان أن أعدد من غير سبب ما دمت قادراً وأجد في نفسي الاستطاعة على العدل بين الزوجتين، وماذا يرى سماحتكم في هذا الموضوع ولاسيما التعدد خاصة، جزاكم الله خيراً؟","title":"هل يتزوج الثانية دون عيب أو نقص في الأولى","answer":"الجواب: لا مانع من التعدد وإن كانت الزوجة الموجودة صالحة وطيبة ليس فيها مرض ولا علة ولو كانت تنجب لا حرج في ذلك إذا كنت بحمد الله قادراً على الزواج وعلى العدل فالحمد لله، الله يقول سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3]، والنبي ﷺ تزوج عدة من النساء عليه الصلاة والسلام وليس في أزواجه علة.\nفالمقصود أنه ﷺ تزوج وهكذا الصحابة تزوجوا، منهم من تزوج ثنتين وتزوج ثلاث، ومنهم من تزوج أربع، فالأمر في هذا واسع والحمد لله، إنما المؤمن يحرص أن يعدل ويجتهد في العدل بين الزوجتين أو الثلاث أو الأربع، والزواج فيه مصالح؛ فيه عفة الفرج وعفة النظر وفيه كثرة النسل، وفيه إحسان للنساء أيضًا حتى النساء فيه إحسان إليهن، فإن وجود نساء ليس لهن أزواج هذا من المصائب وفيه خطر، فكون المرأة تعطى نصف زوج، يعني: يحصل لها نصف أو ثلث أو ربع يعفها وينفق عليها ويحصل لها بسببه النسل هذا خير عظيم ومصلحة كبيرة، خير من بقائها في البيت بدون زوج، فكونها يحصل لها ربع الزوج أو ثلثه أو نصفه خير من بقائها في بيتها بدون زوج لوجوه كثيرة ومصالح جمة للزوج والزوجة جميعًا من كثرة النسل وعفة فرجها وعفة فرجه، وغض بصرها وغض بصره، وإيناسها في هذه الدنيا وقضاء وطرها وقضاء وطره، فالمصالح كثيرة، ومن ذلك تكثير الأمة، فإن وجود النسل بين الزوجين من زوجتين أو أكثر أكثر للأمة، والنبي ﷺ قال: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالمطلوب تكثير الأمة، تكثير الأولاد الصالحين من الرجال والنساء، فالمؤمن يجتهد ويسأل الله التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، بالرغم من أن شطر هذه الكلمة موجه للنساء جزاكم الله خيرًا سماحة الشيخ إلا أني أجد في نفسي الرغبة أكثر ولاسيما وقد قرأت كثيراً عن تعدد العوانس في البيوت؟\nالشيخ: من المصائب أن كثيرًا من الناس اليوم يدعو إلى عدم التعدد وربما اغتروا بما يقوله بعض النصارى ومن شابه النصارى في ذلك، وكثير منهم يحبذ أن يكون الزوج باقياً على واحدة ويندد بالأزواج الذين يعددون وهذا كله غلط، وكله تشبه بالنصارى ، أو تأثر بما قالوه أو قاله من التحق بهم أو شاركهم في رأيهم أو اقتدى بهم في أخلاقهم، والشريعة الإسلامية العظيمة جاءت بالتعدد وكان التعدد قبلنا أكثر، كان عند داود مائة امرأة عليه الصلاة والسلام، وتزوج سليمان تسعاً وتسعين، في رواية: سبعين، كان التعدد في شريعة التوراة أكثر أما في شريعة محمد ﷺ فاقتصر العدد على أربع فأقل للأمة ما عدا النبي ﷺ فله تسع عليه الصلاة والسلام، هذا من رحمة الله جل وعلا أن جعل العدد أربعًا فأقل في هذه الأمة لحكمة بالغة، أما مصالح التعدد فشيء لا يحصى، مصالح التعدد فيه شيء واضح، المصالح كثيرة للرجال والنساء، النساء يحصل لهن العفة وقضاء الوطر والإنفاق عليهن، ودخول الزوج عليهن واحترامهن، والدفاع عنهن وهيبة الرجل إذا دخل عليها، وسلامتها في الأغلب من تعلق غيره بها، إلى غير ذلك من المصالح، ثم الإنفاق عليها ثم وجود الولد الذي يهبها الله ولدًا على يديه فيحصل لها بذلك خير عظيم إذا أصلح الله الولد، وقد يكون عدة أولاد من الرجال والنساء، فالمصالح كثيرة، فهو ينتفع وهي تنتفع، والأسرة كلها تنتفع، فإن كثرة النسل فيه نفع للجميع وتكثير للأمة، كما أن في ذلك صيانة لها وحماية لها وعفة لفرجها وإنفاقًا عليها وإحسانًا إليها، وحرصاً على كل ما يصونها من كل بلاء و شر. نعم.\nالمقدم: بارك الله فيكم، بعض النساء سماحة الشيخ تعتقد أن الزواج من أجل النفقة فقط، فإذا كانت موظفة ولها دخل أو لها تجارة أو كذا لا تريد إلا رجلا خاليًا؟\nالشيخ: هذا غلط، هذا من الغلط، الزواج يراد منه مصالح كثيرة:\nيراد منه طيب العشرة بين الزوجين والأنس في هذه الدنيا والتمتع بينهما المتعة الحسنة الصالحة فيما بينهما.\nويراد منه أيضاً إنجاب الأولاد الصالحين حتى تكثر الأمة ويكثر فيها الصلاح والخير.\nويراد منه أيضاً عفة الفرج عما حرم الله وعفة النظر عما حرم الله.\nويراد من ذلك أيضاً تقليل الفساد في الأرض فإن وجود الرجال والنساء بدون زواج من أعظم الأسباب للفساد في الأرض وكثرة الزنا والفواحش، فإذا تزوجت وتزوج الشاب صار هذا من أعظم الأسباب للصيانة والحماية وقلة الفساد في الأرض، فالزواج ينفع هذا وهذا، ولهذا قال ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء .\nفالزواج فيه خير للجميع لا مجرد النفقة فقط، فيه مصالح كثيرة غير النفقة. نعم.\nالمقدم: بارك الله فيكم، بعض الأزواج سماحة الشيخ أساء إلى مبدأ التعدد؟\nالشيخ: لا شك أن الزوج إذا لم يعدل أساء إلى التعدد وأساء إلى الشريعة وأساء إلى المسلمين، فالواجب على الزوج أن يتقي الله وأن يحسن فيما عليه وأن يؤدي الواجب وأن يكون حريصاً على العدل بين الزوجتين فأكثر حتى لا يظلم نفسه وحتى لا يسبب النفرة من التعدد بأسباب عمله، وحتى أيضاً لا تقع المشاكل بين الأسرتين وتكثر الخصومات في المحاكم، هذا كله يسبب المشاكل، أما العدل والإحسان وطيب العشرة فهو يسبب الخير الكثير للأسرتين وللمجتمع كله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7079/هل-يتزوج-الثانية-دون-عيب-او-نقص-في-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14203.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":8983,"question":"نعود في هذه الحلقة سماحة الشيخ إلى رسالة الأخ: بابكر آدم سليمان سوداني أخونا عرضنا جزءًا من أسئلته في حلقة مضت وفي هذه الحلقة يقول: أنا متزوج ومستقر بمنطقة، ولي عمل بمنطقة أخرى تبعد حوالي مسافة يومين بالسيارة، وحصل أن تزوجت بمنطقة عملي وكنت أقيم في مكان عملي زهاء شهرين أو ثلاثة وإذا أتيت إلى مكان استقراري أقيم حوالي أسبوع أو أسبوعين فهل هذا صحيح أم فيه مخالفة للشريعة في العدل بين الزوجات؟","title":"كيف يعدل وله زوجتان في منطقتين متباعدتين","answer":"الجواب: الواجب عليك أن تعدل بينهما حسب الطاقة والإمكان، فتنقل التي في مستقرك إلى محل عملك حتى تعدل بينهما أو تنقل الجديدة إلى محلك الأول حتى تعدل بينهما، أو تستسمحهما، فإذا سمحت الأولى ولم تلحقها حرجًا فلا بأس بذلك الحق لهما، فإذا سمحت الأولى عن بعض حقها فلا بأس.\nالمقصود أن عليك أن تتحرى العدل حسب طاقتك، إما بنقل الأولى إلى محل عملك، أو نقل الثانية إلى محل أصلك إلى محل بلدك الأولى حتى تجمع بينهما هناك وحتى تعدل بينهما، أو تستسمح الأولى عما يحصل عليها من النقص، فإذا سمحت فالحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7141/كيف-يعدل-وله-زوجتان-في-منطقتين-متباعدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17408.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":9463,"question":"هذه رسالة وردت من السائلة: (م. ن. ر) من الخبر في المملكة، تقول هذه السائلة في رسالتها: أنا امرأة متزوجة ولي أولاد حصل بيني وبين زوجي مشاكل، فهو متزوج من امرأة أخرى، ويؤدي إليها كل الحقوق وأنا لا يعرف من حقوقي شيئاً، ولا يريد أن أذهب إلى أهله منذ سنتين، فهل يجوز لي أن أقاطع أهله بسبب ابنهم، أفيدوني أفادكم الله؟","title":"ما يعدل مع زوجته ومنعها من زيارة أهله","answer":"الجواب: هذا شيء بينك وبينه إن صلحت أنت وإياه فالحمد لله، وإلا فالمحكمة تنظر بينكما، ....... خصومة، هذه مسألة خصومة، فإذا سمحت وصلحت وصبرت على ما قال لك فلا بأس وهذا إليك، فإن لم تصبري فالأمر يرجع فيه إلى المحكمة، والمحكمة تنظر في الأمر بينك وبين زوجك، أصلح الله حال الجميع.\nالمقدم: هذا بالنسبة لما لها من حقوق؟\nالشيخ: نعم.\nالمقدم: لكن هل يجوز له أن يمنعها من زيارة أهله؟\nالشيخ: عليها السمع والطاعة، عليها السمع والطاعة لزوجها فيما أمرها به بالمعروف، وقد يكون زيارتها لأهله تضره، وقد يكون منعها؛ لأنها إذا زارت أهله قالت: فيه كذا، وقالت: فيه كذا، وقالت: فيه كذا. المقصود إذا منعها من أهله تمتنع.\nالمقدم: ولا إثم عليها؟\nالشيخ: ما عليها إثم، ما هو بضروري تزور أهله، المقصود إذا منعها من أهله أو من جيرانه أو من فلان أو فلان لا تزوره تمتنع تصبر، وأما حقوقها فهذا بينها وبينه عند القاضي إلا أن تسمح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7620/ما-يعدل-مع-زوجته-ومنعها-من-زيارة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25509.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":9650,"question":"تسأل الأخت من مكة أيضاً وتقول: أنا متزوجة من مدة عشر سنوات، وقد حصل بيني في يوم من الأيام وبين زوجي خصام، حيث قال لي: أحضري طعام العشاء فرفضت طاعته، وقلت له: لن أحضر لك الطعام حتى توصلني إلى أهلي، فوقف معي ساعتين ثم اتجه إلى منطقة أخرى ولم يقل لي أي شيء، فهل هو آثم وأنا آثمة في عدم طاعته، أم لا، أفيدوني وماذا أفعل حتى أرضي زوجي وفقكم الله؟","title":"رفضت طاعة زوجها وتخاف من الإثم","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، وإحسان الخلق، وطيب الكلام، وتنفيذ الأوامر من إحضار الطعام أو غيره من الشاي أو القهوة أو حاجات أخرى مما أباح الله، هذا هو الواجب على الزوجة، والواجب على الزوج كذلك أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال الله : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فحق الزوج أكبر وهي لها حق عليه أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، بالإنفاق عليها نفقة أمثالها، كسوتها كسوة أمثالها، يخاطبها بالكلام الطيب لا بالسب واللعن، بل بالكلام الطيب والأسلوب الحسن، وهي كذلك تخاطبه بالكلام الطيب والأسلوب الحسن، وتسمع وتطيع في أوامره، لا تعصيه في الأوامر التي ليس فيها حرج شرعاً، ليس فيها منكر، كإحضار الطعام، إحضار الشاي، عمل شيء آخر مما أباح الله مما جرت به العادة، أن تفعله الزوجة مع زوجها، هذا هو الواجب على المرأة حتى تستقيم الأحوال، وحتى تستمر العشرة الطيبة.\nأما إذا أمرها بما لا يجوز كأن يقول لها: تحضر له الخمر أو الدخان أو ما أشبهه مما حرم الله، أو تسمع معه الأغاني والملاهي لا يلزمها ذلك؛ لأن الله يقول جل وعلا: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] ويقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فإذا أمرها بالمعصية ليس لها أن تطيعه، ولكن ترد عليه بالرد الطيب: يا فلان! هذا لا يجوز، هداك الله، أعاذك الله من الشيطان، هذا أمر لا يجوز لي ولا لك، وليس لي أن أعينك على ما حرم الله، يكون عندها أسلوب حسن تعضه وتذكره بالله عز وجل، ولكن لا تطيعه في المعاصي، وعليها أن تخدمه الخدمة المعروفة المعتادة بين أمثالهم؛ لأن الأسر تختلف فإذا كان مثلها يخدم مثله والعادة أنها تخدمه في الأسر المماثلة لهم في بلادهم فإنها تخدمه.\nأما إذا كانت من أسرة تخدم فإن عليه أن يخدمها إذا استطاع ذلك عليه أن يخدمها عملاً بالعادة المعروفة؛ لأن الشرط العرفي كالنطقي ولكن إذا تسامحت وخدمت كما خدمت فاطمة رضي الله عنها بنت النبي ﷺ زوجها علي ، كانت تطحن وتخدم وتصلح الطعام رضي الله عنها وأرضاها، فهكذا ينبغي للزوجة أن تتسامح وأن تخدم حتى ولو كان مثلها يخدم إذا تنازلت وتسامحت كان هذا من طيب الأخلاق ومن حسن السيرة، ومن أسباب استمرار العشرة، لكن إذا كان مثلها يخدم وأسرة تخدم وتيسر للزوج أن يخدمها فذلك حق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7821/رفضت-طاعة-زوجها-وتخاف-من-الاثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25106.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9886,"question":"يسأل أيضاً ويقول: هل على الزوجة خدمة أم زوجها أم لا؟ وما الحكم في ذلك؛ لأن هذا سبب مشكلة عندنا في البيت، ويجعلني أحياناً ألجأ إلى التفكير في الطلاق، وقد سألت في بلدتي مصر أحد المشايخ فقال: حاول أن توفق بين أمك وزوجتك، علماً بأن الزوجة يتيمة وليس لها أحد سواي، ولي منها أبناء ووالدتي ليست كبيرة السن ولله الحمد وعندها بنات في المنزل، والتوفيق بينهما أصبح مستحيلاً، فهل يجوز لي أن أعمل لي بيتاً مستقلاً لي وزوجتي وأترك والدتي وإخوتي، ما الحكم في ذلك؟ بارك الله فيكم.","title":"هل على الزوجة خدمة أم زوجها؟","answer":"الجواب: خدمة المرأة لزوجها وأهل زوجها أمر يختلف بحسب العرف في البلاد، وكان أزواج النبي ﷺ يخدمن بيوتهن، وكانت فاطمة رضي الله عنها تخدم بيتها، في الطحن والعجن والخبز وغير ذلك؛ وكنس البيت ونحو ذلك. فالذي ينبغي للمرأة أن تخدم زوجها وتخدم البيت، وإذا كان في البيت أمه أو أخته أو بناته، فالمشروع لها أن تخدمهن إذا كان العرف في بلادها كذلك.\nأما إذا كان العرف في الأسرة أو في البلد أو في القبيلة التي هي فيها، أنها تخدم وأنها لا تقوم بالخدمة هي، بل يستجلب لها خادمة، فإنه لا يلزمها وعلى الزوج إذا استطاع أن يأتي بالخادمة إلا أن تسمح بالخدمة، وتقوم بها من غير جبر لها فقد أحسنت في ذلك.\nفالحاصل: أن هذا الأمر يختلف ويتنوع بحسب عرف البلاد، إذا حصلت المشاحة والمشاقة، والأفضل للزوج أن يتحرى في هذا الأسلوب الحسن، وأن يرضي المرأة بما يستطيع من المال عند وجود النزاع حتى تخدم بنفس طيبة، حتى تخدم أمه، تخدم بناته أخواته الصغار، ونحو ذلك يكون بالأسلوب الحسن والكلام الطيب، والمساعدة المالية إذا حصلت المشاقة ولم يتضح العرف الذي يقنعها بأن تقوم بالخدمة في بيتها، والله ولي التوفيق. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم، ولكن إذا استطاع أن يرضي والدته وينتقل في بيت مستقل لا حرج عليه؟\nالشيخ: لا حرج عليه، إلا أن تأبى والدته، إذا كانت الوالدة تأبى أن يخرج؛ لأنها محتاجة إليه أو لأسباب أخرى فلا ينبغي الخروج؛ لأن برها واجب، طاعتها مهمة، وقد يكون إخوته الذين في البيت لا يقومون مقامه، ولا يسدون مسده.\nفالحاصل: أنه ينبغي له أن يلاحظ أمه، ويستشيرها، فإذا سمحت فلا مانع من خروجه في بيت مستقل.\nأما إن كانت محتاجة إليه، أو كان هناك أسباب تدعو إلى عدم سماحها بخروجه فلا يخرج، بل يصبر ويحاول التوفيق بينها وبين زوجته ويرضي الزوجة بما يستطيع ولو بالمال حتى تمشي الأمور على الوجه المطلوب وحتى لا يخسر أمه بسبب زعلها عليه وغضبها عليه، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8045/هل-على-الزوجة-خدمة-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26402.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9953,"question":"يسأل أيضاً ويقول: يحصل أحيانًا بعض الخلافات والمناقشة الحارة بين الزوجين فتغضب الزوجةُ زوجها، وهذه المناقشة غالباً ما تكون في أمور دنيوية، فهل تأثم المرأة بإغضاب زوجها؟ أفيدونا أفادكم الله.","title":"هل تأثم المرأة بإغضاب زوجها أثناء النقاش بينهما","answer":"الجواب: إذا كان إغضابها له بغير حق تأثم ولا يجوز لها أن تنازع ولا أن تؤذيه بالكلام، أما إن كان بحق بأن أنكرت عليه منكر، يتساهل في الصلاة فأنكرت عليه، يشرب المسكر فأنكرت عليه وناصحته فغضب فهي مأجورة غير مأزورة بل مشكورة.\nفالمقصود إن كان إغضابها له بحق فهي مأجورة وإن كان بغير حق فهي آثمة ولا يجوز لها إغضابه بدون حق، وعليها الكلام الطيب والسمع والطاعة في المعروف، لكن إذا كان هو يتعاطى المعاصي فأنكرت عليه ونصحته ووجهته إلى الخير فالواجب عليه أن يقبل منها وأن يشكرها وأن لا يغضب لأنها محسنة ومأجورة وناصحة فجزاؤها أن يزداد حبها وأن يشكرها على ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8121/هل-تاثم-المراة-باغضاب-زوجها-اثناء-النقاش-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27407.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10258,"question":"رسالة من المنطقة الشرقية في المملكة بعث بها أحد الإخوة يقول: المتعاقد طبيب (أ. ل. ح. د): أخونا له قضية مع زوجته يذكر أولاً: أنه على خلاف دائم معها، لأسباب يصفها بأنها تافهة في كثير من الأحيان؟","title":"الخلافات الدائمة بين الزوجين ووسائل تلافيها","answer":"الجواب: ننصحهما بالحلم والرفق والتواصي بالحق والصبر وعدم النزاع وعدم الطلاق، نوصي الجميع بالتعاون على الخير والتواصي بالخير، وعدم المنازعة، نوصي المرأة بالسمع والطاعة لزوجها في المعروف، نوصي الزوج بالصبر والحلم وعدم العجلة في الطلاق أو الضرب أو السب، كل واحد منهما عليه أن يتحمل ويستعمل الرفق في كل الأمور، لقوله ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شان ، ولأن هذا العمل داخل في وقوله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228].\nفالمشاجرة الدائمة والنزاع من أسباب الطلاق، وهكذا السب والشتم، فالواجب على كل منهما حفظ اللسان عما لا ينبغي، وحفظ الجوارح عما لاينبغي، والرفق بالأمور والحلم والصبر. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8428/الخلافات-الداىمة-بين-الزوجين-ووساىل-تلافيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27908.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10540,"question":"السائلة أم عبد الله من الرياض تقول: امرأة تشتكي من زوجها حيث إنه متزوج من امرأة أخرى، وتقول: بأنه لا يعدل مع أنه شخص ملتزم ويؤدي الفروض بأوقاتها ومستقيم وتحمد الله على ذلك، ويطلب منها ألا تستخدم موانع الحمل، أما الثانية فقد ترك لها حرية الاختيار، ما هي نصيحتكم سماحة الشيخ لهم؟","title":"حكم التفريق بين الزوجتين في استخدام موانع الحمل","answer":"الجواب: نصيحتي للجميع الأول أن يعدل الزوج ويتقي الله في ذلك؛ لأن الله أوجب عليه العدل بين الزوجتين في القسم والنفقة، فلا يجر على واحدة منهن، بل يجب أن يعدل بينهما، وأما كونه يمنع هذه من الحمل من تعاطي الحبوب ولا يمنع الأخرى، هذا قد يكون له نظر في ذلك لأسباب تقتضي ذلك، وهذا محل نظر، إذا كان ما هناك أسباب تقتضي ذلك فالواجب أن يسمح لهما جميعًا؛ لأن كل واحدة تريد الولد، أما إذا كانت الممنوعة من الولد يضرها الولد مع المرض يضرها.... لها أسباب معقولة هو معذور، أما أن يمنعها من الولد بغير أسباب ويأذن للأخرى فهذا فيه نوع من الجور.\nفالواجب أن يسمح لهما جميعاً ولا يجوز لهما منع الحمل كلاهما، لا يجوز له ولا لها، بل يجب عليهما أن يجتهدا في أسباب الحمل؛ لأن الرسول ﷺ، أمر بتزوج الولود الودود وقال: إني مكاثر بكم الأمم يوم القيامة فالمطلوب تكثير النسل، يشرع للزوج والزوجة أن يجتهدا في تكثير النسل، ولعل الله ينفعهما بذلك، فإن من النعمة العظيمة أن يرزقا ذرية طيبة، فلا وجه للمنع، ولا وجه للاتفاق على المنع أيضاً إلا لعلة شرعية، لأسباب شرعية تقتضي المنع الموقت، كأن تكون مريضة يضرها الحمل كأن يكون معها رضيع يضره الحمل، أو يضرها هي أيضاً الحمل، المقصود إذا كان لأسباب شرعية فلا بأس، أما منع هذه بدون سبب شرعي، أو هذه بدون سبب شرعي، أو منعهما بدون سبب شرعي كل هذا لا يجوز، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8715/حكم-التفريق-بين-الزوجتين-في-استخدام-موانع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28412.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11174,"question":"هذا السائل أرسل بهذا السؤال من الزلفي (ع. م. م) يقول: سماحة الشيخ: والدي متزوج ثلاث نساء مع والدتي ولكن أبي لا يأتي والدتي علمًا بأنها هي أم الأولاد، من مدة تزيد ما يقارب على ست سنوات تقريبًا، وكان السبب في ذلك هو: أن والدي كان يأتي متأخرًا من الليل إذا كان يومها، وبعكسه مع نسائه الأخريات، ووالدتي لم تصبر على هذه الحالة وعلى هذا الظلم وغيرها، فقالت له: إذا كان هذا حضورك لي وهذه حالك معي فلا تحضر،  هل الإثم على والدي الذي ترك والدتي مدة ست سنوات أم على والدتي التي قالت: لا تحضر، عليها شيء، وهي تقصد بالحضور المتأخر من هذا الزوج، وإحضاره الطفل يجعله ينام في فراش والدتي، أرجو منكم الإجابة يا سماحة الشيخ؟","title":"العدل بين الزوجات مطلب شرعي","answer":"الجواب: لاشك أنه أخطأ لأن الواجب عليه العدل، إلا إذا كان بلغها قال: إن كانت ... وإلا طلقت هذا قد اعتذر إليها، أما كونه يقسم للثلاث ويتساهل في حق الوالدة ولا يأتي إلا في آخر الليل أو يضيعها هذا منكر ما يجوز، هذا ظلم، بل الواجب عليه إما أن يعدل وإما أن يطلق، إلا إذا رضيت قالت: أنا سامحة ولو ما جئت، إن جئت فلا بأس وإن ما جئت فلا بأس فلا بأس إذا سمحت لا بأس. سودة رضي الله عنها أم المؤمنين بنت زمعة أراد النبي ﷺ طلاقها فقالت: يا رسول الله دعني في حبالك وأنا سامحة عن حقي لعائشة فأقرها في حباله وبقيت زوجة له ولم يطلقها برضاها، فإذا سمحت والدتك فلا بأس، وإلا فلها طلب الطلاق إما أن يعدل وإما أن يطلق، والإثم عليه إذا كانت لم تسمح. نعم. المقدم: سماحة الشيخ: العدل بين الزوجات أمر مطلوب هل من كلمة توجيهية لأولئك الذين يعددون؟ الشيخ: نعم. الواجب عليهم جميعًا تقوى الله سبحانه وأن يعدلوا، فالذي عنده زوجتان أو ثلاث أو أربع الواجب عليه تقوى الله، وأن يعدل أو يخير المرغوب عنها يقول: إن شئت صبرت وإن شئت طلقت، أما أن يظلمها ويؤذيها، لا. بل يجوز له أن يقول لها: أنتِ سامحة فلا بأس وإلا طلقتكِ، فإن سمحت فالحمد لله وإلا طلقها.  أما أن يظلمها ولا يطلق لا يجوز، بل يجب العدل في المبيت وغيره؛ لأن الله جل وعلا أوجب العدل والله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، فالواجب العدل بين الزوجات، ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فعلى الزوج أن يعدل بين الزوجتين أو أكثر، وإذا رغب عن إحداهن يقول لها: أنا راغب أنت تصبرين متى شئت جئت وإلا فلا، وإلا طلقتكِ، لا بأس قد برئ إذا سمحت لا يضره ذلك ولا حرج عليه، وإذا لم تسمح يطلقها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9354/العدل-بين-الزوجات-مطلب-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29021.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":11180,"question":"من جدة رسالة بتوقيع أحد الإخوة يقول: أخوكم في الله سعد، الأخ سعد يقول: الزوجة التي لا تصلي ليس بإرادتها؛ بل بسبب الوساوس، هل يجوز لزوجها معاشرتها وأن تبقى معه، فهي لا تستطيع الوضوء ولا حتى التيمم لمرضها كما قلت: بالوسواس، هل تصلي بدون وضوء؟","title":"كيفية العمل مع الزوجة التي لا تصلي بسبب الوساوس","answer":"الجواب: الواجب تعليمها وتوجيهها، وأن الوساوس التي تعتريها لا يجوز لها أن تميل إليها وأن تستعملها حتى تضيع الصلاة، بل يجب أن تدعها وأن تصلي، وعليك أن توضح لها ذلك وأن تأمرها بذلك، ولو بالتأديب ولو بالضرب المناسب غير المبرح؛ لأن ترك الصلاة كفر أكبر، فلابد أن تعتني بهذا الأمر وأن تلزمها بالصلاة وأن توجهها إلى الخير؛ حتى تدع الوساوس وحتى تصلي الصلاة التي فرض الله عليها، هذا يحتاج إلى جهاد وصبر لابد؛ لأن الجهل داء عضال. فلابد من التعليم والتوجيه والإرشاد منك ومن أمها وأبيها إن كان لها أبوان من أقاربها، لابد من التعاون على البر والتقوى حتى تفهم الأمر الشرعي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9369/كيفية-العمل-مع-الزوجة-التي-لا-تصلي-بسبب-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37214.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":11500,"question":"سوداني مقيم في المملكة اسمه (جعفر . س) يقول: أنا رجل متزوج، ونويت الزواج من امرأة أخرى، لكن أخفيت ذلك عن زوجتي، فهي إن أخبرتها ستعارض بطبيعة الحال، فما حكم الإسلام في إخفائي لذلك الأمر عنها؟ جزاكم الله خيرًا.","title":"حكم إخفاء الرجل زواجه بالثانية عن زوجته الأولى","answer":"الجواب:  لا حرج في ذلك أن تخفي عنها؛ لكن متى تزوجت لابد من العدل، لابد من العدل بينهما إلا أن ترضى الأخيرة بعدم القسم لها فلا بأس، وإلا فلابد من العدل، تقسم لهذه ولهذه، سواء سواء، نعم. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9678/حكم-اخفاء-الرجل-زواجه-بالثانية-عن-زوجته-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38311.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":13797,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل أخوكم عوض محمود من جمهورية مصر العربية ومقيم في السعودية جدة، يقول: أنا متزوج زوجة وقد أنجبت أربع بنات، وأريد الزواج من امرأة أخرى لكي تنجب لي أولاد ذكور، فماذا تنصحونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يرغب بالزواج بالثانية لإنجاب البنين","answer":"الجواب: هذا طيب، هذا من الأسباب، والتوفيق بيد الله قد تحمل هذه ذكرًا بعد حين، وقد تتزوج امرأة تأتي بذكر وقد تأتي بإناث الأمر بيد الله، إذا تزوجت من باب الأسباب وتسأل ربك أن الله يمنحك ذرية من الذكور طيبة، لا بأس، وهذه التي أتت بأربع قد تأتي بذكور بعد ذلك، ربك على كل شيء قدير، والأمر بيده  ليس بيدها ولا بيدك، تسأل ربك أن الله يسر لك الذرية الطيبة من الذكور والإناث من هذه ومن غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/12168/توجيه-لمن-يرغب-بالزواج-بالثانية-لانجاب-البنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53617.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":14130,"question":"رسالة وصلت إلى البرنامج من قطر - الدوحة باعثها مستمع من هناك يقول (م. م. ع) مقيم في الدوحة، أخونا له جمع من الأسئلة في أحد أسئلته يقول: هل يجوز للرجل أن يتزوج بامرأتين بدون علم إحداهما، مع إيهامه الثانية أنه غير متزوج؟","title":"حكم الزواج بالثانية دون علم الأولى","answer":"الجواب: هذا فيه تفصيل: يجوز أن يتزوج ثانية وثالثة بدون علم السابقات لا بأس بذلك، إذا كان مثلاً سافر إلى بلد من البلدان وتزوج فيها ويأتي إليها وقت سفره إلى هناك لا بأس بذلك. أما في البلد الواحدة فلا بد من العلم حتى يقسم بينهما وحتى يعدل بينهما، وليس له أن يوهمها أنه لا زوجة له، بل يعلم ويخبرها بأن عنده زوجة؛ لأن هذا من الخداع، فلا بد أن يعلمها أن له زوجة إذا كان في بلد واحد، يقول: نعم. ويقسم لهما جميعًا وينصفهما ويعطيهما حقهما، وليس له الخداع والمكر. أما في بلاد أخرى مثل سافر للدراسة فله أن يتزوج في البلد حتى يعف نفسه ولو ما شاور المرأة ولو ما علم المرأة، لا يضره ذلك ما دام ليس عنده العدد المسموح به وهو أربع بل عنده فرصة، فإذا كان ما عنده إلا واحدة يأخذ ثانية، ما عنده الاثنتين يأخذ ثالثة، عنده ثلاث يأخذ رابعة لا بأس لا يزيد على الأربع.\nالمقصود أنه إذا احتاج إلى ذلك وأراد أن يتزوج ليس من شرط ذلك أن يعلم زوجته إذا كانت في بلد أخرى، لكن مع مراعاة قسم الواجب والعدل في النفقة وغير هذا مما يجب على الزوج من جهة العدالة. نعم، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12569/حكم-الزواج-بالثانية-دون-علم-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61506.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15373,"question":"سماحة الشيخ، هذه أختنا (م. ن. هـ) من الرياض، كتبت الحقيقة رسالة بأسلوبها الخاص، وتذكر بأنها زوجة لديها سبعة من الأولاد وبنت، زوجها تزوج عليها، تقول: لقد استشارها في ذلك، ووافقت فقط أن يعدل بينها وبين ضرتها، وتزوج، ولكنه -تقول- خان العهد الذي بيننا وهو العدل؛ لذلك فإنه لا يسأل عن أولاده، ولا يرد السلام عندما أسلم عليه، ويهددني دائمًا بالطلاق، ويميل إلى زوجته الأخرى في جميع أمورها. سماحة الشيخ تقول: هل يجب علي الصبر في ذلك، أم أشتكيه إلى الشرع أو إلى المحكمة؟مأجورين.","title":"حكم من يميل إلى زوجته الأخرى","answer":"الجواب: الواجب عليه أن يعدل، وأن يتقي الله سبحانه، هذا هو الواجب عليه، أن يعدل بينكما في القسم، وغيره، هذا الواجب عليه، فإن لم يعدل فأنت بالخيار إن شئت صبرت وسامحتيه، وإن شئت طلبت الطلاق، قولي: طلقني أو اعدل، فإذا أبى ارفعي الأمر إلى المحكمة، إما أن يعدل، وإما أن يطلق، إلا أن ترضي وتصبري، فلا بأس.  فإذا لم يعدل، ولم يطلق، فلك أن ترفعي إلى المحكمة أنت أو وليك إلى المحكمة؛ ليلزمه بالطلاق أو بالعدل، نسأل الله للجميع الهداية. المقدم: اللهم آمين، سماحة الشيخ، ميل كثير من الأزواج بعد أن يعددوا هل من كلمة توجيهية لهؤلاء؟\nالشيخ: الواجب على من كان عنده زوجتان أو ثلاث أو أربع، الواجب عليه أن يعدل في القسم وغيره، هذا هو الواجب؛ لأن الله أوجب العدل على الأزواج، وكان النبي ﷺ كان يقسم بين أزواجه ويعدل، ويقول: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك كان يقسم بين نسائه ويعدل، وهو خير الناس وأفضلهم -عليه الصلاة والسلام-. فالواجب على من كان عنده زوجتان أو ثلاث أو أربع أن يعدل بينهن، وكذلك في النفقة إلا إذا كان عند إحداهن أولاد أكثر ينفق عليها بقدر حاجتها، بقدر حاجاتها وأولادها، كل واحدة بقدر حاجتها وأولادها، وعليه أن يقسم بينهن بالسوية في الليل والنهار، ويتقي الله في البشاشة وطلاقة الوجه، مع كل واحدة، لا يعبس في واحدة وينشرح للأخرى، عليه أن يتقي الله، وأن يراقب الله؛ لأن الله يقول: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ[النساء:19] هذا هو الواجب عليه، ويقول ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالواجب العدل أو الطلاق، إما أن يعدل، وإما أن يطلق، إلا أن تسمح، تقول: أنا سامحه، لا بأس تجيني متى شئت فلا بأس، سودة لما أراد النبي ﷺ طلاقها قالت: «يا رسول الله، أبقني في حبالك، وأنا سامحة عن حقي لـعائشة» فأسقطت حقها وأبقاها النبي ﷺ، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13876/حكم-من-يميل-الى-زوجته-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56704.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15775,"question":"سؤاله الأخير في هذه الحلقة يقول: إنّ والده تزوج بامرأة أخرى، وحينئذٍ أساء معاملة والدته إساءة بالغة، رغم أن والدته يصفها بأنها محسنة إلى والده، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"توجيه لمن يسيء تعامل الزوجة الأولى","answer":"الجواب: الواجب نصيحة الوالد، وترغيبه في العدل، وتحذيره من الجور؛ لأنه يأثم بذلك، الواجب عليه العدل بين الزوجتين، وفي الحديث الصحيح يقول النبي ﷺ: من كانت له امرأتان، فمال إلى إحداهما، جاء يوم القيامة وشقه مائل فهي عقوبة ظاهرة، نسأل الله العافية.  فالمقصود: أن الواجب العدل، كذلك الواجب أن ينصح الوالد، ويحرض على العدل، والوالدة توصى بالصبر والتحمل ومسامحة الوالد، حتى يجتمع الشمل، وحتى يهديه الله إذا رأى منها السماح، والكلام الطيب، قد يرجع إلى الصواب، ويخضع، ويقدر لها شعورها الطيب، وإذا أبى إلا عدم العدل، فلها أن تطلب الطلاق، إن أحبت الطلاق لها أن تطلب الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14368/توجيه-لمن-يسيء-تعامل-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74205.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":15984,"question":"هذا سؤال من السائلة مسلمة من العراق، محافظة ديالي، تقول: أنا امرأة متزوجة، ولي أربعة أطفال، وقد تزوج زوجي امرأة ثانية، ولها أطفال أيضًا، والمشكلة أنه لا يعدل في معاملته بيننا، فقد انصرف عني كليًا، حتى كأنه لا وجود لي في البيت، وأطفالي يدرسون، ويحتاجون إلى مصاريف الدراسة، ولكنه لا يعطيهم، وأنا لا أستطيع أن أطلب منه، وللعلم فنحن نسكن والزوجة الثانية في نفس المسكن، وأخشى على أطفالي من الضياع من هجره للجميع، وعدم اهتمامه، فما رأيكم في هذا؟","title":"توجيه لمن لا يعدل في تعامله بين زوجتيه","answer":"الجواب: الواجب عليه تقوى الله، الواجب على الزوج أن يتقي الله، وأن يعدل، قد قال النبي ﷺ: من كان له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل فالعدل واجب في النفقة بينهما والمساواة بينهما في القسمة، فإذا جار على السائلة فهذا عليه إثم في ذلك إلا إذا كان خيرها بين الطلاق وبين الصبر، فلا حرج عليه، إذا خيرها واختارت البقاء معه على ظلمه وعدم عدله فلا بأس عليه إذا خيرها، أما أنه يمنع الطلاق، ويمنع العدل، فهذا لا يجوز له. أما أولاده فعليه نفقتهم، والواجب عليه مطلقًا طلق أو لم يطلق، عليه أن يعدل في أولاده، ويحسن إليهم، ويقوم بحاجاتهم حسب طاقته، وإذا استطاعت أن تأخذ من ماله شيئًا لحاجتها فلا بأس، إذا كان لديها مال واستطاعت السائلة أن تأخذ من ماله شيئًا بغير علمه قدر حاجتها بالمعروف لأولادها ولها فلا حرج، فقد ثبت عن النبي ﷺ أنه رخص لامرأة أبي سفيان أن تأخذ من ماله بالمعروف ما يكفيها ويكفي بنيها، فإذا وجدت له مالًا تستطيع أن تأخذ منه شيئًا لها ولأولادها بغير علمه بالمعروف من غير تبذير ومن غير إسراف، فلا حرج في ذلك -إن شاء الله-، وإن لم تستطع فينبغي لها أن تتصل بأقاربه وإخوانه والذين يعزهم ويقدرهم حتى ينصحوه، حتى يشيروا عليه، لعله يهتدي، ولعله يقوم بالواجب. وينبغي لها أن تكثر من سؤال الله له الهداية حتى يوفق للعدل، وإن كان هناك حاكم شرعي في الأحوال الشخصية، يمكن أن ترفع الأمر إليه، فلا مانع من أن ترفع إليه حتى يلزمه بالعدل، ولكن مهما أمكن أن يكون ذلك من طريق المصلحين من أقاربه وجيرانه والناس الذين يعزهم فهو أولى، الإصلاح بينها وبينه من طريق الإخوان الطيبين حتى ينفق وحتى يعدل، فهذا أولى من الشكوى وأحوط وأقرب إلى السلامة، نسأل الله للجميع الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14612/توجيه-لمن-لا-يعدل-في-تعامله-بين-زوجتيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68007.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":16002,"question":"هل ما يقدمه الزوج لأهل زوجته الأخرى من صدقات أو هدايا هل يؤثر ذلك في العدل بين الزوجات؟","title":"هل يشترط العدل بين أهل الزوجات؟","answer":"الجواب: لا بأس بذلك، لا حرج -إن شاء الله-، لا يؤثر، المهم العدل بينهما في أنفسهما، أما إذا أعطى أهل إحدى زوجتيه لفقرهم، أو لإحسانهم إليه، أو لأسباب أخرى، فليس هذا من باب العدل بين الزوجات، لا حرج عليه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14622/هل-يشترط-العدل-بين-اهل-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74710.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":17232,"question":"تقول: يا سماحة الشيخ -هذه الأخت الطبيبة- أبي عليه ديونٌ، رغم أنه يشتغل، إلا أنه لا يستطيع تسديد هذه الديون، ولقد طلب منا نحن الأخوات البنات على مساعدته، واتفقن مع أخواتي على مبلغٍ محدد يدفع من الكل، زوجي يرفض أن أساعد أهلي، بالرغم من، أولًا: أصرف على نفسي، وعلى ابنتي، وعلى البيت من كل النواحي: إيجار، وكهرباء، ومأكل، وملبس، وغير ذلك، بل العكس أنا أساعده بالرغم من أن راتبه كبير، زوجي يصرف جميع ما يملك من الراتب على أهله، لبناء بيتٍ لأبيه، وأنا لم أعترض، بل العكس أساعده، المبلغ الذي أساعد به أهلي يعتبر جزءًا بسيطًا بالنسبة للراتب الذي أتقاضاه، أهلي موجودون في المنطقة التي أدرس بها، وهم الذين ساعدوني في أمور الحياة، مثلًا: لو احتجت الذهاب إلى مكان ما، أو طبيب، وغير ذلك، لعل لكم توجيه؟","title":"ما حكم إعانة المرأة لوالدها وزوجها رافض؟","answer":"الجواب: نعم، الواجب مساعدة والدك، عليكم أن تساعدوا الوالد، النبي ﷺ يقول: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فعليكم أن تساعدوا والدكم، ولو لم يرض الزوج، ما له حق يمنعكم، ولو منعكم ما له حق، عليكم أن تساعدوا الوالد، ولو لم يرض الزوج، هذا من أهم الصلة، ومن أهم البر، فعليكن أن تساعدن والدكن في قضاء دينه، وفي نفقة بيته، ولو لم يرض الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/16060/ما-حكم-اعانة-المراة-لوالدها-وزوجها-رافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59109.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":18460,"question":"يقول السائل محمد من جمهورية مصر العربية: رجل يريد أن يتزوج زوجة ثانية على زوجته الأولى، هل لها الحق أي: الزوجة الأولى، أن تطلب ملابس وذهبا مثل الزوجة الثانية في الزواج، أم ماذا يفعل تجاهها؟","title":"هل يلزم مساواة الزوجة الأولى بالثانية في يوم زواجها؟","answer":"الجواب: لا، لا يلزمه ذلك، يلزمه الإنفاق عليها بالمعروف، وأما ما يعطيه الزوجة الجديدة من مهر وغيره هذا يختص بالجديدة، لا يلزمه أن يعطي تلك مثلها، ولكن يقسم للجديدة يقسم لها ثلاث إذا كانت ما هي ببكر، وإن كانت بكرًا يقسم لها سبعًا، الجديدة، ثم يعدل، ثم يقسم بين الجميع. وأما أنه يعطيها مثلما أعطى الجديدة من مهر وحلي وملابس شرطتها عليه فلا، لكن يعطيها بعد.. يقسم بينهم بعد الكسوة وغيرها بعدين بعد الزواج، يسوي بينهم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17539/هل-يلزم-مساواة-الزوجة-الاولى-بالثانية-في-يوم-زواجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78507.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19203,"question":"الواقع كدت سماحة الشيخ أطلب من سماحتكم نصيحة إلى الأخوات المتزوجات، فكثير من الإخوة عندما يتزوج وهذه نيته يريد على الأقل أن يكتسب الإنفاق على أخت مسلمة لا عائل لها، زوجته تغادر المنزل وتقوم وتولول وتفسد أولاده عليه وتؤنبهم عليه أيضًا.","title":"حكم تذمر النساء من تعدد الزوجات والإنكار على الأزواج","answer":"الجواب:\n\nهذا منكر مثلما سمعت، هذا منكر وليس لها أن تفعل ذلك، ليس لأي زوجة أن تنكر على زوجها ذلك، وليس لها أن تعترض عليه، وليس لها أن تسيء إليه، ولا إلى أولاده، وإنما فعل ما أباح الله له.\n\nنعم، إذا ظلم، إذا جار عليها.. إذا لم يعدل فلها أن تتكلم، ولها أن تشكوه إلى المحكمة إلا أن تصبر وتحتسب، أما ما دام لم تر منه إلا الخير، أو حتى الآن ما بعد فعل شيئًا فإنها تصبر وتحتسب، وترجو الله أن يقدر لها الأصلح، وأن يعينها على الصبر، وسوف يجعل الله فرجًا ومخرجًا يقول الله  في كتابه العظيم: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، ويقول سبحانه: كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَكُمْ وَعَسَى أَنْ تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَكُمْ وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [البقرة:216].\n\nفالله هو اللي يعلم ، فربما كان هذا الزواج سببًا لعطفه عليها ومزيد محبته لها؛ لأنه رأى من الثانية ما لم ير من الأولى، ورأى أن خصال الأولى أحسن وأن سيرتها أطيب، وأن دينها أكمل، فيعطف عليها أكثر، وربما طلق الثانية وزاد حبه للأولى، فلا ينبغي لها أن تجزع من هذا، فربما كان خيرًا لها، وإن نجح في زواجه وعدل بينهما فالحمد لله، المؤمن يحب لأخيه ما يحب لنفسه، فينبغي لها أن تحب لأخواتها في الله أن يرزقهن الله أزواجًا وذريات، هكذا المؤمن مع أخيه، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه.\nوهكذا لا تؤمن المؤمنة حتى تحب لأختها ما تحب لنفسها، هذا معنى كلامه عليه الصلاة والسلام؛ لأن قوله يعم الرجال والنساء، والله المستعان. نعم.\nالمقدم: والله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18400/حكم-تذمر-النساء-من-تعدد-الزوجات-والانكار-على-الازواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88807.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19204,"question":"ننتقل بعد هذا إلى قضايا أخرى ورسائل أخرى، فرسالة وصلت إلى البرنامج من المستمع ( علي. س.س.) من الجنوب، أخونا يسأل سماحة الشيخ عن الحكم فيمن يعدد الزوجات، وهل يصغي إلى الأقوال القائلة بأن ذلك يخالف الفطرة؟ وجهونا جزاكم الله خيرًا.","title":"ترك تعدد الزوجات سبب في كثرة العوانس في البيوت","answer":"الجواب: قد شرع الله  لعباده تعدد النساء إذا استطاع الزوج ذلك، ولم يخف الجور والعول في قوله جل وعلا: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:3] ، وقد تزوج النبي ﷺ عدة من النساء، وتوفي ﷺ وعنده تسع، وهذا من خصائصه عليه الصلاة والسلام فيما زاد عن أربع. أما الأمة فليس لهم إلا أربع فقط، قد فرق النبي ﷺ بين من أسلم على أكثر من أربع، وأمره أن يفارق الزائد، وخيره أن يختار أربعًا ويفارق ما زاد على ذلك. فالواجب على المسلم أن يقف عند حد الله، وأن لا يزيد على ما شرع الله وهو الأربع، فإذا استطاع أن يتزوج أربعًا وقام بحقهن فلا حرج عليه في ذلك، بل ذلك أفضل له إذا استطاع ذلك لما في ذلك من المصالح من: عفة فرجه، وغض بصره، وتكثير الأمة، وتكثير النسل الذي قد ينفع الله به الأمة، وقد يعبد الله ويدعو لوالديه فيحصل لهم بذلك الخير العظيم. ولولا أنه أمر مطلوب وأمر مشروع وفيه مصالح جمة لما فعله النبي عليه الصلاة والسلام، فهو أفضل الناس وخير الناس وأحرصهم على كل خير عليه الصلاة والسلام، وقد جعل الله في تزوجه بالعدد الكثير من النساء مصالح كثيرة في تبليغ الدعوة ونشر الإسلام من طريق النساء، ومن طريق الرجال. فإذا تزوج المؤمن ثنتين أو ثلاثًا أو أربعًا لمصالح شرعية؛ لأنه يحتاج إلى ذلك، أو لقصد تكثير الأولاد أو لقصد كمال العفة وكمال غض البصر؛ لأنه قد لا تكفيه الواحدة أو الاثنتان أو الثلاث، فكل هذا أمر مطلوب شرعي، ولا يجوز لأي مسلم ولا لأي مسلمة الاعتراض على ذلك، ولا يجوز انتقاد ذلك، ولا يجوز لأي إذاعة ولا أي تلفاز أن ينشر ما يعارض ذلك، بل يجب على جميع وسائل الإعلام أن تقف عند حدها، وليس لها أن تنكر هذا الأمر المشروع، ولا يجوز لمن يقوم على وسائل الإعلام أن ينشر مقالًا لمن يعترض على ذلك، لا في الوسائل المقروءة ولا في الوسائل المسموعة، ولا في الوسائل المرئية، بل يجب على وزراء الإعلام في الدول الإسلامية أن يحذروا ذلك، وأن يتقوا الله وأن يبتعدوا عما حرم الله . وهل يرضى مسلم أن تبقى النساء عوانس في البيوت! والإنسان يستطيع يأخذ ثنتين وثلاثًا وأربعًا، هذا لا يجوز أن يفعله مسلم أو يراه مسلم يخاف الله ويرجوه. وهل يجوز لمسلمة تخاف الله وترجوه أن تنكر ذلك، وهي تعلم يقينًا أن كونها مع زوج عنده زوجة أو زوجتان أو ثلاث خير لها من بقائها بدون زوج حتى تموت عانسة لا زوج لها، وربما رزقها الله بهذا الزوج الذي ليس لها إلا جزء منه، ربما رزقها الله ذرية صالحة تنفعها في الدنيا والآخرة، وربما حصل لها بذلك عفة فرجها وغض بصرها وحسن سمعتها وسلامة عرضها. فالواجب على الدول الإسلامية عامة وعلى حكومتنا خاصة إظهار هذا الأمر وتأييد هذا الأمر، والإنكار على من عارض هذا الأمر في أي وسيلة مرئية أو مسموعة أو مقروءة، بل يجب إنكار ذلك. وإنه ليسوءني كثيرًا ويسوء كل مسلم يخاف الله أن يسمع في إذاعة أو يشاهد في تلفاز أو يقرأ في صحيفة من يعترض على شرع الله، ويدعو إلى الاقتصار على الواحدة، إلا على الوجه الشرعي إذا خاف ألا يقوم بالواجب، أو عجز عن أن يقوم باثنتين، فهذا قد وضحه الله  لكن من استطاع أن يتزوج ثنتين أو ثلاثًا أو أربعًا فلا حرج عليه، بل هو مأجور ومشكور إذا نوى بذلك إظهار دين الله وتكثير الأمة وغض بصره وإحصان فرجه، والإحسان إلى أخواته في الله المحتاجات إلى النكاح، فهو مشكور ومأجور. والواجب على جميع المسلمين وعلى جميع المسلمات أن يرضوا بما شرع الله، وأن يحذروا الاعتراض على ما شرعه الله، وأن يخافوا نقمته سبحانه وعقابه في اعتراضهم ومخالفتهم لأمر الله ، وقد قال الله  في كتابه العظيم: ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:9] ، فأخشى على من كره هذا المشروع أن يحبط عمله وأن يخرج من دينه وهو لا يشعر، نسأل الله العافية. وقال تعالى: ذَلِكَ بِأَنَّهُمُ اتَّبَعُوا مَا أَسْخَطَ اللَّهَ وَكَرِهُوا رِضْوَانَهُ فَأَحْبَطَ أَعْمَالَهُمْ [محمد:28].\nفالمقصود أنه يجب على المؤمن أن يرضى بما شرعه الله، وأن يبغض ما أبغضه الله، وأن يكره ما كرهه الله، وأن يحب ما أحبه الله في جميع الأمور، إذا كان مسلمًا مؤمنًا يخاف الله ويرجوه، نسأل الله للجميع الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا الواقع سماحة الشيخ وأنتم تتفضلون بهذا التوجيه المخلص كثيرًا ما نسمع عن كثرة العوانس في البيوت، لعل لكم من كلمة سماحة الشيخ؟ الشيخ: هذا ثابت عندنا، ولهذا نوصي جميع النساء أن لا يمتنعن من الزوج الذي عنده زوجة، نوصيهن جميعًا أن يحرصن على عفتهن وسمعتهن الحسنة، وعلى حفظ فروجهن وغض أبصارهن، وعلى حفظ أعراضهن أن يبادرن بالزواج ولو كن جارات، ولو كانت ثانية أو ثالثة أو رابعة، فأنا أوصي بهذا، وأسأل الله أن يهدينا جميعًا لما يرضيه، وأوصي الأزواج القادرين أن يتزوجوا وأن يعفوا كثيرًا من نساء أمتهم، وأن يحرصوا على تكثير النسل، وعلى حفظ فروجهم وغض أبصارهم بما أحل الله لا ما حرم الله. كثير من الناس -نعوذ بالله- يأبى أن يتزوج ثانية، ولكنه يرضى بالصديقات فيما حرم الله، وتعلم زوجته ذلك، وذلك قد يكون أحب إليها من زوجة مسلمة على الوجه الشرعي، فهي تعلم عنه أنه يذهب إلى المحرمات وإلى الصديقات وإلى الزنا، ولكن لا يهمها ذلك، لكن لو تزوج لغضبت وأنكرت ولا حول ولا قوة إلا بالله، فترضى بالحرام أو تقر الحرام ولكن لا ترضى بالحلال، هذه من المصائب، ومن ضعف الدين ومن ضعف الإيمان وقلة البصيرة، نسأل الله الهداية والسلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18399/ترك-تعدد-الزوجات-سبب-في-كثرة-العوانس-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88806.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]},{"id":19703,"question":"الواجب في العدل بين النساء هل هو في المبيت والنفقة فقط؟","title":"فيم يكون العدل بين النساء","answer":"الجواب: في القسم والنفقة، كلٌّ على قدره، يقول ﷺ: اللهم هذا قسمي فيما أملك، فلا تلمني فيما تملك ولا أملك، يقسم بينهم، والنفقة على حسب أحوالهن، فمَن كانت عندها عيال فإنَّ نفقتها أكثر، كلٌّ على قدره.","link":"https://binbaz.org.sa/fatwas/21693/فيم-يكون-العدل-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%81%D9%8A%D9%85%20%D9%8A%D9%83%D9%88%D9%86%20%D8%A7%D9%84%D8%B9%D8%AF%D9%84%20%D8%A8%D9%8A%D9%86%20%D8%A7%D9%84%D9%86%D8%B3%D8%A7%D8%A1.mp3","categories":["الحقوق الزوجية","تعدد الزوجات","المشكلات الزوجية"]}]
